package com.andye.warmod.block;
import net.minecraft.server.level.ServerLevel;import net.minecraft.world.InteractionResult;import net.minecraft.world.item.Item;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.world.level.block.state.BlockState;
public final class MissileSiloGuidanceFrameItem extends Item {public MissileSiloGuidanceFrameItem(Properties p){super(p);}@Override public InteractionResult useOn(UseOnContext c){if(c.getLevel().isClientSide())return InteractionResult.SUCCESS;if(!(c.getLevel() instanceof ServerLevel level))return InteractionResult.FAIL;BlockState state=level.getBlockState(c.getClickedPos());net.minecraft.core.BlockPos centre;net.minecraft.core.Direction facing;if(state.is(ModBlocks.MISSILE_SILO)){var silo=MissileSiloBlock.resolve(level,c.getClickedPos(),state);if(silo==null)return InteractionResult.FAIL;centre=silo.getBlockPos();facing=silo.facing();}else if(state.is(ModBlocks.MISSILE_SILO_GUIDANCE_FRAME)){facing=state.getValue(MissileSiloGuidanceFrameBlock.FACING);int tier=state.getValue(MissileSiloGuidanceFrameBlock.TIER);int y=(tier-1)*2+(state.getValue(MissileSiloGuidanceFrameBlock.LAYER)==MissileSiloGuidanceFrameLayer.LOWER?1:2);centre=state.getValue(MissileSiloGuidanceFrameBlock.PART).resolveCentre(c.getClickedPos().below(y),facing);}else return InteractionResult.PASS;if(!MissileSiloGuidanceFrameStructure.installNext(level,centre,facing,c.getPlayer()))return InteractionResult.FAIL;c.getItemInHand().consume(1,c.getPlayer());return InteractionResult.SUCCESS_SERVER;}}